1: import { PlanAnualAuditoriaMid } from "src/app/core/services/plan-anual-auditoria-mid.service";
2: import { Component, ElementRef, Inject, ViewChild } from "@angular/core";
3: import { MAT_DIALOG_DATA, MatDialogRef } from "@angular/material/dialog";
4: import { NuxeoService } from "src/app/core/services/nuxeo.service";
5: import { ModalService } from "src/app/shared/services/modal.service";
6: import { AlertService } from "src/app/shared/services/alert.service";
7: import { ReferenciaPdfService } from "src/app/core/services/referencia-pdf.service";
8: import { environment } from "src/environments/environment";
9: import * as XLSX from "xlsx";
10: 
11: @Component({
12:     selector: "app-cargar-archivo",
13:     templateUrl: "./cargar-archivo.component.html",
14:     standalone: false
15: })
16: export class CargarArchivoComponent {
17:   archivo: File | null = null;
18:   @ViewChild("fileInput", { static: false }) fileInput!: ElementRef;
19: 
20:   constructor(
21:     public dialogRef: MatDialogRef<CargarArchivoComponent>,
22:     private readonly PlanAnualAuditoriaMid: PlanAnualAuditoriaMid,
23:     private readonly nuxeoService: NuxeoService,
24:     private readonly alertService: AlertService,
25:     private readonly modalService: ModalService,
26:     private readonly referenciaPdfService: ReferenciaPdfService,
27: 
28:     @Inject(MAT_DIALOG_DATA)
29:     public data: {
30:       usuario_id: number;
31:       usuario_rol: string;
32:       tipoArchivo: string;
33:       idTipoDocumento: number;
34:       descripcion: string;
35:       id: string;
36:       vigenciaId: number;
37:       cargaLambda: boolean;
38:       tipo: string;
39:       tipoIdReferencia: number;
40:       referencia: string;
41:       metadatos?: Record<string, any>;
42:       nuevo?: boolean;
43:       documentoIdActualizar?: string;
44:       soloSeleccionar?: boolean;
45:     }
46:   ) {}
47: 
48:   onArchivoSelecionado(event: any): void {
49:     const input = event.target as HTMLInputElement;
50:     const file = input.files ? input.files[0] : null;
51: 
52:     if (file) {
53:       if (
54:         (this.data.tipoArchivo === "pdf" && file.type !== "application/pdf") ||
55:         (this.data.tipoArchivo === "xlsx" &&
56:           file.type !==
57:             "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet")
58:       ) {
59:         alert(
60:           "Por favor seleccione un archivo válido según el tipo especificado."
61:         );
62:         this.removerArchivo();
63:         return;
64:       }
65: 
66:       this.archivo = file;
67:     }
68:   }
69: 
70:   onArchivoInputClick(): void {
71:     this.fileInput.nativeElement.click();
72:   }
73: 
74:   removerArchivo(): void {
75:     this.archivo = null;
76:     this.fileInput.nativeElement.value = "";
77:   }
78: 
79:   async cargarArchivo(): Promise<void> {
80:     if (!this.archivo) {
81:       this.alertService.showErrorAlert("No se ha seleccionado ningún archivo.");
82:       return;
83:     }
84: 
85:     if (this.data.soloSeleccionar) {
86:       this.retornarArchivo();
87:       return;
88:     }
89: 
90:     // Validar fechas del Excel antes de enviar (solo para cargue masivo de actividades)
91:     if (this.data.cargaLambda && this.data.tipo === "actividades") {
92:       const erroresFechas = await this.validarFechasExcel(this.archivo);
93:       if (erroresFechas.length > 0) {
94:         const filas = erroresFechas
95:           .map((e) => `• Fila ${e.fila}: ${e.mensaje}`)
96:           .join("\n");
97:         this.alertService.showErrorAlert(
98:           `El archivo contiene errores en las fechas:\n\n${filas}`
99:         );
100:         return;
101:       }
102:     }
103: 
104:     if (this.data.cargaLambda) {
105:       this.cargarConLambda().then((success) => {
106:         if (success) {
107:           this.cargarConNuxeo().then((nuxeoResponse) => {
108:             this.guardarReferencia(
109:               nuxeoResponse,
110:               this.data.referencia,
111:               this.data.id,
112:               0,
113:               false,
114:               this.data.metadatos
115:             );
116:           });
117:         }
118:       });
119:     } else {
120:       this.cargarConNuxeo().then((nuxeoResponse) => {
121:         this.guardarReferencia(
122:           nuxeoResponse,
123:           this.data.referencia,
124:           this.data.id,
125:           this.data.tipoIdReferencia,
126:           true,
127:           this.data.metadatos,
128:           this.data.nuevo
129:         );
130:       });
131:     }
132:   }
133: 
134:   /**
135:    * Lee el Excel y valida que 'Fecha Fin' >= 'Fecha Inicio' en cada fila de datos.
136:    * Las fechas vienen como texto en formato YYYY-MM-DD según la plantilla.
137:    * Se agrega T00:00:00 al parsear para evitar desfase de zona horaria (UTC vs local).
138:    * Omite la fila de instrucciones que contiene texto explicativo.
139:    */
140:   private validarFechasExcel(
141:     archivo: File
142:   ): Promise<{ fila: number; mensaje: string }[]> {
143:     return new Promise((resolve) => {
144:       const reader = new FileReader();
145: 
146:       reader.onload = (e: any) => {
147:         try {
148:           const data = new Uint8Array(e.target.result);
149:           const workbook = XLSX.read(data, { type: "array" });
150:           const hoja = workbook.Sheets[workbook.SheetNames[0]];
151: 
152:           // true para leer el texto tal cual sin conversión automática de fechas
153:           const filas: any[] = XLSX.utils.sheet_to_json(hoja, {
154:             defval: null,
155:             raw: true,
156:           });
157: 
158:           const errores: { fila: number; mensaje: string }[] = [];
159: 
160:           filas.forEach((fila, index) => {
161:             const numeroFila = index + 2; // +2 porque fila 1 es encabezado
162: 
163:             const valorInicio: string | null = fila["Fecha Inicio"];
164:             const valorFin: string | null = fila["Fecha Fin"];
165: 
166:             if (
167:               !valorInicio ||
168:               !valorFin ||
169:               String(valorInicio).toLowerCase().includes("texto") ||
170:               String(valorInicio).toLowerCase().includes("yyyy")
171:             ) {
172:               return;
173:             }
174: 
175:             const valorInicioStr = String(valorInicio).trim();
176:             const valorFinStr = String(valorFin).trim();
177: 
178:             const fechaInicio = new Date(valorInicioStr + "T00:00:00");
179:             const fechaFin = new Date(valorFinStr + "T00:00:00");
180: 
181:             if (isNaN(fechaInicio.getTime())) {
182:               errores.push({
183:                 fila: numeroFila,
184:                 mensaje: `Fecha de inicio inválida: "${valorInicioStr}". Use el formato YYYY-MM-DD.`,
185:               });
186:               return;
187:             }
188: 
189:             if (isNaN(fechaFin.getTime())) {
190:               errores.push({
191:                 fila: numeroFila,
192:                 mensaje: `Fecha de fin inválida: "${valorFinStr}". Use el formato YYYY-MM-DD.`,
193:               });
194:               return;
195:             }
196: 
197:             // Comparar solo la parte de fecha (sin hora) para evitar falsos positivos
198:             const inicio = new Date(
199:               fechaInicio.getFullYear(),
200:               fechaInicio.getMonth(),
... (422 linhas no arquivo)

200:               fechaInicio.getMonth(),
201:               fechaInicio.getDate()
202:             );
203:             const fin = new Date(
204:               fechaFin.getFullYear(),
205:               fechaFin.getMonth(),
206:               fechaFin.getDate()
207:             );
208: 
209:             if (fin < inicio) {
210:               errores.push({
211:                 fila: numeroFila,
212:                 mensaje: `La fecha de fin (${valorFinStr}) no puede ser anterior a la fecha de inicio (${valorInicioStr}).`,
213:               });
214:             }
215:           });
216: 
217:           resolve(errores);
218:         } catch (error) {
219:           console.error("Error al leer el archivo Excel para validación:", error);
220:           resolve([]); // Si no se puede leer, dejar pasar y que el backend valide
221:         }
222:       };
223: 
224:       reader.onerror = () => resolve([]);
225:       reader.readAsArrayBuffer(archivo);
226:     });
227:   }
228: 
229:   private async cargarConLambda(): Promise<boolean> {
230:     try {
231:       const base64 = await this.nuxeoService.fileABase64(this.archivo!);
232:       console.log("vigencia Masivo", this.data.vigenciaId);
233: 
234:       let payload: any = {};
235:       switch (this.data.tipo) {
236:         case "auditorias":
237:           payload = {
238:             base64data: base64,
239:             complement: {
240:               plan_auditoria_id: this.data.id,
241:               vigencia_id: this.data.vigenciaId,
242:               usuario_id: this.data.usuario_id,
243:               usuario_rol: this.data.usuario_rol,
244:               fase_id: environment.AUDITORIA_FASE.PROGRAMACION,
245:               estado_id: environment.AUDITORIA_PADRE_ESTADO.BORRADOR_ID,
246:             },
247:             type_upload: "auditorias",
248:           };
249:           break;
250:         case "actividades":
251:           payload = {
252:             base64data: base64,
253:             complemento: { auditoria_id: this.data.id },
254:             type_upload: "actividades",
255:           };
256:           break;
257:       }
258: 
259:       const response: any = await this.PlanAnualAuditoriaMid.post(
260:         `cargue-masivo/${this.data.tipo}`,
261:         payload
262:       ).toPromise();
263: 
264:       if (response?.Data) {
265:         console.log("Archivo enviado exitosamente al MID", response);
266:         this.resultados(response.Data);
267:         return true;
268:       } else {
269:         this.alertService.showErrorAlert(
270:           "La respuesta de cargue masivo no contiene datos válidos."
271:         );
272:         return false;
273:       }
274:     } catch (error: any) {
275:       console.error("=== ERROR SERVERLESS ===");
276:       console.error("status:", error?.status);
277:       console.error("message:", error?.message);
278:       console.error("error.error:", JSON.stringify(error?.error, null, 2));
279:       console.error("error completo:", JSON.stringify(error, null, 2));
280:       console.error("=======================");
281: 
282:       this.alertService.showErrorAlert(
283:         "Error al enviar el archivo a cargue masivo. Por favor, revise el log."
284:       );
285:       return false;
286:     }
287:   }
288: 
289:   private async cargarConNuxeo(): Promise<any> {
290:     const archivoConDatos = {
291:       IdTipoDocumento: this.data.idTipoDocumento,
292:       nombre: this.archivo!.name,
293:       descripcion: this.data.descripcion,
294:       file: this.archivo!,
295:     };
296: 
297:     return new Promise((resolve, reject) => {
298:       this.nuxeoService.guardarArchivos([archivoConDatos]).subscribe({
299:         next: (response) => {
300:           console.log("Archivo subido a Nuxeo", response);
301:           resolve(response[0]);
302:         },
303:         error: (error: Error) => {
304:           this.alertService.showErrorAlert("Error al subir el archivo.");
305:           console.error("Error al subir el archivo", error);
306:           reject(error);
307:         },
308:       });
309:     });
310:   }
311: 
312:   guardarReferencia(
313:     nuxeoResponse: any,
314:     referencia_tipo: string,
315:     referencia_id: string,
316:     tipo_id: number,
317:     mostrarMensaje: boolean,
318:     metadatos?: Record<string, any>,
319:     nuevo: boolean = false
320:   ): void {
321:     if (nuxeoResponse.res.Enlace) {
322:       this.referenciaPdfService
323:         .guardarReferencia(
324:           nuxeoResponse.res,
325:           referencia_tipo,
326:           referencia_id,
327:           tipo_id,
328:           metadatos,
329:           nuevo,
330:           this.data.documentoIdActualizar
331:         )
332:         .subscribe({
333:           next: (response) => {
334:             console.log("Referencia guardada exitosamente", response);
335:             if (mostrarMensaje) {
336:               this.alertService.showSuccessAlert("Archivo subido exitosamente.");
337:             }
338:             this.dialogRef.close(true);
339:           },
340:           error: (error) => {
341:             console.error("Error al guardar la referencia", error);
342:             this.dialogRef.close(false);
343:           },
344:         });
345:     }
346:   }
347: 
348:   resultados(data: any): void {
349:     const totalCorrectos = data.Correctos?.length ?? 0;
350:     const totalErroneos = data["Erróneos"]?.length ?? 0;
351: 
352:     if (totalCorrectos > 0 && totalErroneos === 0) {
353:       this.modalService.mostrarModal(
354:         `<div style="text-align:center">
355:           <p style="font-size:2rem; margin:0">✅</p>
356:           <p style="font-size:1.1rem; margin-top:8px">
357:             Se cargaron correctamente <strong>${totalCorrectos}</strong> registro(s).
358:           </p>
359:         </div>`,
360:         "success",
361:         "Cargue exitoso"
362:       );
363:       return;
364:     }
365: 
366:     const icono = totalCorrectos > 0 ? "warning" : "error";
367:     const titulo =
368:       totalCorrectos > 0 ? "Cargue con observaciones" : "Cargue fallido";
369: 
370:     let mensaje = "";
371: 
372:     if (totalCorrectos > 0) {
373:       mensaje += `
374:         <div style="background:#e8f5e9; border-radius:8px; padding:10px; margin-bottom:12px">
375:           ✅ <strong>${totalCorrectos}</strong> registro(s) cargado(s) correctamente
376:           <span style="color:#555; font-size:0.9rem">(filas: ${data.Correctos.join(", ")})</span>
377:         </div>`;
378:     }
379: 
380:     if (totalErroneos > 0) {
381:       mensaje += `
382:         <div style="background:#ffebee; border-radius:8px; padding:10px; margin-bottom:8px">
383:           ❌ <strong>${totalErroneos}</strong> registro(s) con error
384:         </div>
385:         <table style="width:100%; border-collapse:collapse; font-size:0.9rem; text-align:left">
386:           <thead>
387:             <tr style="background:#f5f5f5">
388:               <th style="padding:6px 10px; border-bottom:2px solid #ddd; width:60px">Fila</th>
389:               <th style="padding:6px 10px; border-bottom:2px solid #ddd">Error</th>
390:             </tr>
391:           </thead>
392:           <tbody>`;
393: 
394:       data["Erróneos"].forEach((error: any) => {
395:         mensaje += `
396:             <tr>
397:               <td style="padding:6px 10px; border-bottom:1px solid #eee; text-align:center">
398:                 <strong>${error.Idx}</strong>
399:               </td>
... (422 linhas no arquivo)

400:               <td style="padding:6px 10px; border-bottom:1px solid #eee; color:#c62828">
401:                 ${error.Error}
402:               </td>
403:             </tr>`;
404:       });
405: 
406:       mensaje += `</tbody></table>`;
407:     }
408: 
409:     this.modalService.mostrarModal(mensaje, icono, titulo);
410:   }
411: 
412:   retornarArchivo() {
413:     const archivoConDatos = {
414:       ...this.data,
415:       nombre: this.archivo!.name,
416:       archivo: this.archivo!,
417:       fecha_creacion: (new Date()).toLocaleString()
418:     };
419: 
420:     this.dialogRef.close({ documento: archivoConDatos });
421:   }
422: }

