71:             reader.onload = () => {
72:                 let encoded = reader.result!.toString().replace(/^data:(.*,)?/, '');
73:                 if ((encoded.length % 4) > 0) {
74:                     encoded += '='.repeat(4 - (encoded.length % 4));
75:                 }
76:                 resolve(encoded);
77:             };
